"""Prefix to Postfix — scan right to left, appending the operator last.

Time: O(n)   Space: O(n)
"""


class Solution:
    def prefixToPostfix(self, s: str) -> str:
        stack = []
        for ch in reversed(s):
            if ch.isalnum():
                stack.append(ch)
            else:
                left, right = stack.pop(), stack.pop()
                stack.append(left + right + ch)
        return stack[-1]
